// A package that starts child processes. The program's package.json runs it in a Node island.
const { spawn } = require("node:child_process");
exports.start = (command, args) => spawn(command, args, { stdio: ["pipe", "pipe", "pipe"] });
exports.later = (command, args) =>
  new Promise((resolve) => setImmediate(() => resolve(exports.start(command, args))));
exports.each = (scripts, visit) => {
  for (const script of scripts) visit(exports.start("sh", ["-c", script]), script);
};
